const _choco =
    '#Requires -Version 5.1\n'
    '<#\n'
    '.SYNOPSIS\n'
    '  Installs the xcross host requirements on Windows with Chocolatey.\n'
    '\n'
    '.DESCRIPTION\n'
    '  What this script does, in order:\n'
    '\n'
    '    1. Visual Studio 2022 Build Tools with the MSVC and Windows SDK\n'
    '       components (Swift for Windows links against them), unless present\n'
    '       (visualstudio2022buildtools).\n'
    '    2. Swift toolchain 6.4+. The Chocolatey community repository has no Swift\n'
    '       package (the Swift project publishes to winget only), so the latest\n'
    '       release installer is downloaded from download.swift.org and run only\n'
    '       with a valid Apple Authenticode signature.\n'
    '    3. LLVM 20+ (llvm) for clang, llvm-ar and ld64.lld, with its bin on the\n'
    '       user PATH.\n'
    '    4. Python 3.13 (python313), unless a Python 3 already exists.\n'
    '    5. pymobiledevice3 into the user site-packages.\n'
    '\n'
    '  XCROSS_SETUP_ONLY=vs,swift,llvm,python,pymobiledevice3 (set by\n'
    '  `xcross setup --only`) installs just that subset and skips the final\n'
    '  check.\n'
    '\n'
    '  Chocolatey installs machine-wide: run this from an Administrator\n'
    '  PowerShell. Every package or installer is announced with its source URL and\n'
    '  needs a "y" before it is installed. -Yes (or XCROSS_SETUP_ASSUME_YES=1,\n'
    '  which `xcross setup --yes` sets) accepts those prompts up front.\n'
    '\n'
    '  winget and Scoop users: see winget.ps1 and scoop.ps1 next to this file.\n'
    '  Flutter stays manual: https://docs.flutter.dev/get-started/install/windows\n'
    '\n'
    '.PARAMETER Yes\n'
    '  Install everything without asking.\n'
    '\n'
    '.EXAMPLE\n'
    '  powershell -NoProfile -ExecutionPolicy Bypass -File choco.ps1\n'
    '#>\n'
    '[CmdletBinding()]\n'
    'param(\n'
    '  [Alias(\'y\')]\n'
    '  [switch]\$Yes\n'
    ')\n'
    '\n'
    '\$ErrorActionPreference = \'Stop\'\n'
    '# Windows PowerShell 5.1 may still default to TLS 1.0.\n'
    '[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12\n'
    '\$AssumeYes = \$Yes.IsPresent -or (\$env:XCROSS_SETUP_ASSUME_YES -eq \'1\')\n'
    '# Comma-separated subset of vs,swift,llvm,python,pymobiledevice3 to install\n'
    '# (default: all).\n'
    '\$Only = @((\$env:XCROSS_SETUP_ONLY -split \',\') | ForEach-Object { \$_.Trim().ToLowerInvariant() } | Where-Object { \$_ })\n'
    'function Test-Wanted([string]\$Component) { \$Only.Count -eq 0 -or \$Only -contains \$Component }\n'
    '\n'
    '\$MinClang = 20\n'
    '\$MinLld = 19\n'
    '\$MinSwift = [version]\'6.4\'\n'
    '\n'
    'function Write-Info([string]\$Message) { Write-Host "==> \$Message" }\n'
    'function Write-Warn([string]\$Message) { Write-Warning \$Message }\n'
    '\n'
    '\$CanPrompt = [Environment]::UserInteractive -and -not [Console]::IsInputRedirected\n'
    '\n'
    '# Machine-readable progress for xcross. With XCROSS_SETUP_EVENTS=1 (set by\n'
    '# `xcross setup` when it reports NDJSON events) each install step prints a\n'
    '# `##xcross {"step":...,"status":...,"label":...}` line, which xcross turns\n'
    '# into a step event; terminal users never see them.\n'
    '\$EmitSteps = \$env:XCROSS_SETUP_EVENTS -eq \'1\'\n'
    '\$script:Declined = \$false\n'
    '\$script:FailedSteps = @()\n'
    'function Write-Step([string]\$Step, [string]\$Status, [string]\$Label) {\n'
    '  if (\$Status -eq \'start\') { \$script:Declined = \$false }\n'
    '  if (\$Status -eq \'failed\') { \$script:FailedSteps += \$Step }\n'
    '  if (-not \$EmitSteps) { return }\n'
    '  \$marker = [ordered]@{ step = \$Step; status = \$Status; label = \$Label }\n'
    '  Write-Host "##xcross \$(\$marker | ConvertTo-Json -Compress)"\n'
    '}\n'
    '\n'
    '# Ends a step begun with Write-Step: done when \$Ok, skipped when the user\n'
    '# declined its prompt, failed otherwise.\n'
    'function Complete-Step([string]\$Step, \$Ok, [string]\$Label) {\n'
    '  \$status = if (\$Ok) { \'done\' } elseif (\$script:Declined) { \'skipped\' } else { \'failed\' }\n'
    '  Write-Step \$Step \$status \$Label\n'
    '}\n'
    '\n'
    '# Ask before installing third-party software. Returns \$true to proceed.\n'
    'function Confirm-Install([string]\$Name, [string]\$Url, [string]\$What) {\n'
    '  Write-Host \'\'\n'
    '  Write-Host "xcross setup wants to install \$Name"\n'
    '  Write-Host "  from: \$Url"\n'
    '  Write-Host "  what: \$What"\n'
    '  if (\$AssumeYes) {\n'
    '    Write-Host \'Proceeding (-Yes).\'\n'
    '    return \$true\n'
    '  }\n'
    '  if (-not \$CanPrompt) {\n'
    '    Write-Warn "No terminal to confirm \$Name; skipping it (re-run with -Yes to accept)."\n'
    '    \$script:Declined = \$true\n'
    '    return \$false\n'
    '  }\n'
    '  \$answer = Read-Host "Install \$Name? [y/N]"\n'
    '  if (\$answer -match \'^(y|yes)\$\') { return \$true }\n'
    '  Write-Host "Skipped \$Name."\n'
    '  \$script:Declined = \$true\n'
    '  return \$false\n'
    '}\n'
    '\n'
    '# Re-read PATH and SDKROOT from the registry so newly installed tools resolve\n'
    '# in this session without a new terminal.\n'
    'function Update-SessionEnvironment {\n'
    '  \$machine = [Environment]::GetEnvironmentVariable(\'Path\', \'Machine\')\n'
    '  \$user = [Environment]::GetEnvironmentVariable(\'Path\', \'User\')\n'
    '  \$session = @(\$env:Path -split \';\' | Where-Object { \$_ })\n'
    '  \$registered = @(@(\$machine, \$user) -join \';\' -split \';\' | Where-Object { \$_ -and \$session -notcontains \$_ })\n'
    '  \$env:Path = (@(\$session) + \$registered | Select-Object -Unique) -join \';\'\n'
    '  foreach (\$scope in \'User\', \'Machine\') {\n'
    '    \$sdk = [Environment]::GetEnvironmentVariable(\'SDKROOT\', \$scope)\n'
    '    if (\$sdk) { \$env:SDKROOT = \$sdk; break }\n'
    '  }\n'
    '}\n'
    '\n'
    'function Add-UserPath([string]\$Directory) {\n'
    '  \$user = [Environment]::GetEnvironmentVariable(\'Path\', \'User\')\n'
    '  \$entries = @(\$user -split \';\' | Where-Object { \$_ })\n'
    '  if (\$entries -notcontains \$Directory) {\n'
    '    [Environment]::SetEnvironmentVariable(\'Path\', ((\$entries + \$Directory) -join \';\'), \'User\')\n'
    '    Write-Info "Added \$Directory to the user PATH"\n'
    '  }\n'
    '  if ((@(\$env:Path -split \';\') -notcontains \$Directory)) {\n'
    '    \$env:Path = "\$Directory;\$env:Path"\n'
    '  }\n'
    '}\n'
    '\n'
    '# Run a native command, returning its combined output and exit code. Windows\n'
    '# PowerShell 5.1 turns redirected native stderr into terminating errors under\n'
    '# ErrorActionPreference=Stop, so probes relax it locally.\n'
    'function Invoke-Probe([string]\$Path, [string[]]\$Arguments) {\n'
    '  \$ErrorActionPreference = \'Continue\'\n'
    '  \$output = (& \$Path @Arguments 2>&1 | Out-String)\n'
    '  return @{ Output = \$output; Code = \$LASTEXITCODE }\n'
    '}\n'
    '\n'
    '# Run a native command with its output on the console; returns the exit code.\n'
    '# Output goes to the host, not the pipeline, or callers would receive the\n'
    '# command\'s stdout as part of the return value.\n'
    'function Invoke-Native([string]\$Path, [string[]]\$Arguments) {\n'
    '  Write-Info "\$Path \$(\$Arguments -join \' \')"\n'
    '  \$ErrorActionPreference = \'Continue\'\n'
    '  & \$Path @Arguments | Out-Host\n'
    '  return \$LASTEXITCODE\n'
    '}\n'
    '\n'
    'function Get-ToolMajor([string]\$Command, [string]\$Pattern) {\n'
    '  \$tool = Get-Command \$Command -ErrorAction SilentlyContinue\n'
    '  if (-not \$tool) { return \$null }\n'
    '  \$text = (Invoke-Probe \$tool.Source @(\'--version\')).Output\n'
    '  if (\$text -match \$Pattern) { return [int]\$Matches[1] }\n'
    '  return \$null\n'
    '}\n'
    '\n'
    'function Get-SwiftVersion {\n'
    '  \$swift = Get-Command swift -ErrorAction SilentlyContinue\n'
    '  if (-not \$swift) { return \$null }\n'
    '  \$text = (Invoke-Probe \$swift.Source @(\'--version\')).Output\n'
    '  if (\$text -match \'Swift version (\\d+\\.\\d+)\') { return [version]\$Matches[1] }\n'
    '  return \$null\n'
    '}\n'
    '\n'
    '# The LLVM installer does not touch PATH; xcross finds these directories on\n'
    '# its own, but PATH makes clang usable everywhere.\n'
    'function Find-LlvmBin {\n'
    '  foreach (\$root in @(\$env:ProgramW6432, \$env:ProgramFiles, \${env:ProgramFiles(x86)})) {\n'
    '    if (-not \$root) { continue }\n'
    '    \$bin = Join-Path \$root \'LLVM\\bin\'\n'
    '    if (Test-Path (Join-Path \$bin \'clang.exe\')) { return \$bin }\n'
    '  }\n'
    '  return \$null\n'
    '}\n'
    '\n'
    '# studio: 009 - the Swift toolchain ships an ld64.lld without Mach-O iOS\n'
    '# support, so finding *an* ld64.lld is not enough. Like xcross\'s own probe\n'
    '# (darwin_toolchain_resolver.dart), link a 56-byte empty arm64 iOS object\n'
    '# into a dylib: an unsupported linker rejects the platform once it reads it.\n'
    'function Test-IosLinker {\n'
    '  \$words = @(0xfeedfacfL, 0x0100000c, 0, 1, 1, 24, 0, 0, 0x32, 24, 2, 0x000d0000, 0x000d0000, 0)\n'
    '  \$bytes = [byte[]]@(\$words | ForEach-Object { [BitConverter]::GetBytes([uint32]\$_) } | ForEach-Object { \$_ })\n'
    '  \$dir = Join-Path ([IO.Path]::GetTempPath()) ("xcross-ld64-probe-" + [guid]::NewGuid())\n'
    '  New-Item -ItemType Directory -Path \$dir -Force | Out-Null\n'
    '  \$object = Join-Path \$dir \'probe.o\'\n'
    '  [IO.File]::WriteAllBytes(\$object, \$bytes)\n'
    '  \$candidates = @()\n'
    '  \$llvm = Find-LlvmBin\n'
    '  if (\$llvm) { \$candidates += (Join-Path \$llvm \'ld64.lld.exe\') }\n'
    '  \$candidates += @(Get-Command ld64.lld -All -ErrorAction SilentlyContinue | ForEach-Object { \$_.Source })\n'
    '  try {\n'
    '    foreach (\$lld in \$candidates) {\n'
    '      if (-not (Test-Path \$lld)) { continue }\n'
    '      \$probe = Invoke-Probe \$lld @(\'-arch\', \'arm64\', \'-platform_version\', \'ios\', \'13.0\', \'13.0\', \'-dylib\', \'-o\', "\$object.dylib", \$object)\n'
    '      if (\$probe.Output -notmatch \'does not support linking for platform|unknown platform|missing or unsupported -arch\') { return \$true }\n'
    '    }\n'
    '    return \$false\n'
    '  } finally {\n'
    '    Remove-Item -Recurse -Force \$dir -ErrorAction SilentlyContinue\n'
    '  }\n'
    '}\n'
    '\n'
    '# The Microsoft Store "python.exe" alias is a stub that only opens the Store.\n'
    'function Find-Python {\n'
    '  foreach (\$candidate in @(\n'
    '      @{ Command = \'py\'; Args = @(\'-3\') },\n'
    '      @{ Command = \'python\'; Args = @() },\n'
    '      @{ Command = \'python3\'; Args = @() })) {\n'
    '    \$cmd = Get-Command \$candidate.Command -ErrorAction SilentlyContinue\n'
    '    if (-not \$cmd -or \$cmd.Source -like \'*\\WindowsApps\\*\') { continue }\n'
    '    \$probeArgs = \$candidate.Args + @(\'-c\', \'import sys; assert sys.version_info >= (3, 9)\')\n'
    '    if ((Invoke-Probe \$cmd.Source \$probeArgs).Code -eq 0) { return @{ Path = \$cmd.Source; Args = \$candidate.Args } }\n'
    '  }\n'
    '  return \$null\n'
    '}\n'
    '\n'
    '# Native architecture, even from an emulated x64 PowerShell on ARM64.\n'
    '\$arch = \$env:PROCESSOR_ARCHITEW6432\n'
    'if (-not \$arch) { \$arch = \$env:PROCESSOR_ARCHITECTURE }\n'
    '\$isArm64 = \$arch -eq \'ARM64\'\n'
    '\n'
    '# MSVC + Windows SDK components Swift for Windows links against.\n'
    '\$vcComponent = if (\$isArm64) {\n'
    '  \'Microsoft.VisualStudio.Component.VC.Tools.ARM64\'\n'
    '} else {\n'
    '  \'Microsoft.VisualStudio.Component.VC.Tools.x86.x64\'\n'
    '}\n'
    '\$vsComponents = @(\n'
    '  \'Microsoft.VisualStudio.Component.Windows11SDK.22621\',\n'
    '  \'Microsoft.VisualStudio.Component.VC.Tools.x86.x64\'\n'
    ')\n'
    'if (\$isArm64) { \$vsComponents += \'Microsoft.VisualStudio.Component.VC.Tools.ARM64\' }\n'
    '\$vsAdd = @(\$vsComponents | ForEach-Object { \'--add\'; \$_ })\n'
    '\n'
    'function Test-Msvc {\n'
    '  \$programFilesX86 = if (\${env:ProgramFiles(x86)}) { \${env:ProgramFiles(x86)} } else { \$env:ProgramFiles }\n'
    '  if (-not \$programFilesX86) { return \$false }\n'
    '  \$vswhere = Join-Path \$programFilesX86 \'Microsoft Visual Studio\\Installer\\vswhere.exe\'\n'
    '  if (-not (Test-Path \$vswhere)) { return \$false }\n'
    '  \$found = Invoke-Probe \$vswhere @(\'-latest\', \'-products\', \'*\', \'-requires\', \$vcComponent, \'-property\', \'installationPath\')\n'
    '  return \$found.Code -eq 0 -and [bool]\$found.Output.Trim()\n'
    '}\n'
    '\n'
    'function Test-Elevated {\n'
    '  try {\n'
    '    \$identity = [Security.Principal.WindowsIdentity]::GetCurrent()\n'
    '  } catch {\n'
    '    return \$false # Not Windows.\n'
    '  }\n'
    '  return ([Security.Principal.WindowsPrincipal]\$identity).IsInRole(\n'
    '    [Security.Principal.WindowsBuiltInRole]::Administrator)\n'
    '}\n'
    '\n'
    '# Download a vendor installer, check it against \$Sha256 and/or a valid\n'
    '# Authenticode signature from \$Signer (at least one is required), then run it.\n'
    'function Install-SignedInstaller {\n'
    '  param(\n'
    '    [string]\$Name, [string]\$Url, [string]\$What,\n'
    '    [string[]]\$Arguments, [string]\$Signer, [string]\$Sha256,\n'
    '    [int[]]\$OkCodes = @(0, 3010)\n'
    '  )\n'
    '  if (-not \$Signer -and -not \$Sha256) { throw "No way to verify the \$Name installer." }\n'
    '  if (\$Signer -and -not (Get-Command Get-AuthenticodeSignature -ErrorAction SilentlyContinue)) {\n'
    '    Write-Warn "Cannot verify the \$Name installer signature here; install it manually from \$Url."\n'
    '    return \$false\n'
    '  }\n'
    '  if (-not (Confirm-Install "\$Name (official installer)" \$Url \$What)) { return \$false }\n'
    '  \$file = Join-Path ([IO.Path]::GetTempPath()) ("xcross-" + [IO.Path]::GetFileName(([uri]\$Url).AbsolutePath))\n'
    '  try {\n'
    '    Write-Info "Downloading \$Url"\n'
    '    \$ProgressPreference = \'SilentlyContinue\'\n'
    '    Invoke-WebRequest -Uri \$Url -OutFile \$file -UseBasicParsing\n'
    '    if (\$Sha256) {\n'
    '      \$hash = (Get-FileHash -LiteralPath \$file -Algorithm SHA256).Hash\n'
    '      if (\$hash -ne \$Sha256.Trim().ToUpperInvariant()) {\n'
    '        Write-Warn "Refusing to run \${Name}: SHA-256 \$hash, expected \$Sha256."\n'
    '        return \$false\n'
    '      }\n'
    '      Write-Info "SHA-256 \$hash"\n'
    '    }\n'
    '    if (\$Signer) {\n'
    '      \$signature = Get-AuthenticodeSignature -FilePath \$file\n'
    '      \$subject = if (\$signature.SignerCertificate) { \$signature.SignerCertificate.Subject } else { \'<unsigned>\' }\n'
    '      if (\$signature.Status -ne \'Valid\' -or \$subject -notlike "*\$Signer*") {\n'
    '        Write-Warn "Refusing to run \${Name}: signature \$(\$signature.Status), signer \$subject."\n'
    '        return \$false\n'
    '      }\n'
    '      Write-Info "Signed by \$subject"\n'
    '    }\n'
    '    \$process = if (\$file -like \'*.msi\') {\n'
    '      Start-Process -FilePath \'msiexec.exe\' -ArgumentList (@(\'/i\', "`"\$file`"") + \$Arguments) -Wait -PassThru\n'
    '    } else {\n'
    '      Start-Process -FilePath \$file -ArgumentList \$Arguments -Wait -PassThru\n'
    '    }\n'
    '    Update-SessionEnvironment\n'
    '    if (\$process.ExitCode -eq 3010) { Write-Warn "\$Name asks for a reboot to finish installing." }\n'
    '    if (\$OkCodes -notcontains \$process.ExitCode) {\n'
    '      Write-Warn "\$Name installer failed with exit code \$(\$process.ExitCode)."\n'
    '      return \$false\n'
    '    }\n'
    '    return \$true\n'
    '  } finally {\n'
    '    Remove-Item -LiteralPath \$file -Force -ErrorAction SilentlyContinue\n'
    '  }\n'
    '}\n'
    '\n'
    '# Invoke-RestMethod writes a top-level JSON array to the pipeline as a single\n'
    '# object in Windows PowerShell 5.1; enumerate it so filters see each element.\n'
    'function Get-JsonArray([string]\$Url) {\n'
    '  Invoke-RestMethod -UseBasicParsing -Headers @{ \'User-Agent\' = \'xcross-setup\' } \$Url | ForEach-Object { \$_ }\n'
    '}\n'
    '\n'
    '# ---------------------------------------------------------------------------\n'
    '# Chocolatey\n'
    '# ---------------------------------------------------------------------------\n'
    '\n'
    'if (-not (Get-Command choco -ErrorAction SilentlyContinue)) {\n'
    '  throw \'Chocolatey was not found. Install it from https://chocolatey.org/install, or use winget.ps1 / scoop.ps1.\'\n'
    '}\n'
    'if (-not (Test-Elevated)) {\n'
    '  throw \'Chocolatey installs machine-wide and needs an Administrator PowerShell. Re-run from one, or use winget.ps1 / scoop.ps1.\'\n'
    '}\n'
    '\n'
    '# Install or upgrade one community package (`choco upgrade` installs missing\n'
    '# packages too).\n'
    'function Install-Choco {\n'
    '  param([string]\$Id, [string]\$Name, [string]\$What, [string]\$Params)\n'
    '  \$url = "https://community.chocolatey.org/packages/\$Id"\n'
    '  if (-not (Confirm-Install "\$Name (choco \$Id)" \$url \$What)) { return \$false }\n'
    '  \$arguments = @(\'upgrade\', \$Id, \'--yes\', \'--no-progress\')\n'
    '  if (\$Params) { \$arguments += @(\'--package-parameters\', \$Params) }\n'
    '  \$code = Invoke-Native \'choco\' \$arguments\n'
    '  \$ErrorActionPreference = \'Stop\'\n'
    '  Update-SessionEnvironment\n'
    '  if (\$code -eq 3010 -or \$code -eq 1641) { Write-Warn "\$Name asks for a reboot to finish installing." }\n'
    '  if (\$code -in 0, 1641, 3010) { return \$true }\n'
    '  Write-Warn "Chocolatey could not install \$Name (exit code \$code)."\n'
    '  return \$false\n'
    '}\n'
    '\n'
    'if (Test-Wanted \'vs\') {\n'
    '  if (Test-Msvc) {\n'
    '    Write-Step \'vs\' \'skipped\' \'Visual Studio 2022 Build Tools (already installed)\'\n'
    '  } else {\n'
    '    Write-Step \'vs\' \'start\' \'Visual Studio 2022 Build Tools\'\n'
    '    # The package forwards these to vs_BuildTools.exe; --passive shows\n'
    '    # progress instead of its default --quiet.\n'
    '    \$ok = Install-Choco -Id \'visualstudio2022buildtools\' -Name \'Visual Studio 2022 Build Tools\' `\n'
    '        -What \'the MSVC compiler and Windows SDK that Swift for Windows links against (several GB)\' `\n'
    '        -Params ((\$vsAdd + \'--passive\') -join \' \')\n'
    '    Complete-Step \'vs\' \$ok \'Visual Studio 2022 Build Tools\'\n'
    '  }\n'
    '}\n'
    '\n'
    '# Chocolatey has no Swift package (the Swift project publishes to winget\n'
    '# only), so take the latest release installer from swift.org and run it only\n'
    '# with a valid Apple Authenticode signature.\n'
    '\$swiftVersion = Get-SwiftVersion\n'
    'if (Test-Wanted \'swift\') {\n'
    '  if (\$swiftVersion -and \$swiftVersion -ge \$MinSwift) {\n'
    '    Write-Step \'swift\' \'skipped\' "Swift \$swiftVersion (already installed)"\n'
    '  } else {\n'
    '    Write-Step \'swift\' \'start\' \'Swift toolchain\'\n'
    '    \$release = @(Get-JsonArray \'https://www.swift.org/api/v1/install/releases.json\')[-1]\n'
    '    \$tag = \$release.tag\n'
    '    \$platform = if (\$isArm64) { \'windows10-arm64\' } else { \'windows10\' }\n'
    '    \$ok = Install-SignedInstaller -Name "Swift \$(\$release.name)" `\n'
    '        -Url "https://download.swift.org/\$(\$tag.ToLowerInvariant())/\$platform/\$tag/\$tag-\$platform.exe" `\n'
    '        -What "the Swift \$MinSwift+ compiler, runtime and SwiftPM" `\n'
    '        -Arguments @(\'/passive\', \'/norestart\') `\n'
    '        -Signer \'O=Apple Inc.\'\n'
    '    Complete-Step \'swift\' \$ok \'Swift toolchain\'\n'
    '  }\n'
    '}\n'
    '\n'
    '\$llvmBin = Find-LlvmBin\n'
    'if (\$llvmBin) { Add-UserPath \$llvmBin }\n'
    '\$clangMajor = Get-ToolMajor \'clang\' \'clang version (\\d+)\'\n'
    'if (Test-Wanted \'llvm\') {\n'
    '  if (\$clangMajor -and \$clangMajor -ge \$MinClang -and (Test-IosLinker)) {\n'
    '    Write-Step \'llvm\' \'skipped\' "LLVM \$clangMajor (already installed)"\n'
    '  } else {\n'
    '    Write-Step \'llvm\' \'start\' \'LLVM\'\n'
    '    \$ok = Install-Choco -Id \'llvm\' -Name \'LLVM\' `\n'
    '        -What "clang/clang++ \$MinClang+, llvm-ar and ld64.lld for compiling and linking iOS binaries"\n'
    '    if (\$ok) {\n'
    '      \$llvmBin = Find-LlvmBin\n'
    '      if (\$llvmBin) { Add-UserPath \$llvmBin }\n'
    '    }\n'
    '    Complete-Step \'llvm\' \$ok \'LLVM\'\n'
    '  }\n'
    '}\n'
    '\n'
    '\$python = Find-Python\n'
    'if (Test-Wanted \'python\') {\n'
    '  if (\$python) {\n'
    '    Write-Step \'python\' \'skipped\' \'Python 3 (already installed)\'\n'
    '  } else {\n'
    '    Write-Step \'python\' \'start\' \'Python 3.13\'\n'
    '    \$ok = Install-Choco -Id \'python313\' -Name \'Python 3.13\' -What \'the Python runtime that hosts pymobiledevice3\'\n'
    '    if (\$ok) { \$python = Find-Python }\n'
    '    Complete-Step \'python\' \$ok \'Python 3.13\'\n'
    '  }\n'
    '}\n'
    '\n'
    '\$Hint = @{\n'
    '  Swift  = \'https://www.swift.org/install/windows/\'\n'
    '  Llvm   = \'choco upgrade llvm\'\n'
    '  Python = \'choco install python313\'\n'
    '}\n'
    '\n'
    '# ---------------------------------------------------------------------------\n'
    '# pymobiledevice3 and summary\n'
    '# ---------------------------------------------------------------------------\n'
    '\n'
    'if ((Test-Wanted \'pymobiledevice3\') -and -not \$python) {\n'
    '  Write-Step \'pymobiledevice3\' \'failed\' \'pymobiledevice3 (needs Python 3)\'\n'
    '} elseif (Test-Wanted \'pymobiledevice3\') {\n'
    '  Write-Step \'pymobiledevice3\' \'start\' \'pymobiledevice3\'\n'
    '  Write-Info \'Installing pymobiledevice3 with pip (user site-packages)\'\n'
    '  \$pipCode = Invoke-Native \$python.Path (\$python.Args + @(\'-m\', \'pip\', \'install\', \'--user\', \'--upgrade\', \'--prefer-binary\', \'pymobiledevice3\'))\n'
    '  \$ErrorActionPreference = \'Stop\'\n'
    '  if (\$pipCode -ne 0) { Write-Warn \'pip could not install pymobiledevice3.\' }\n'
    '  # pip --user puts console scripts in a per-version Scripts directory.\n'
    '  \$scripts = Invoke-Probe \$python.Path (\$python.Args + @(\'-c\', "import sysconfig; print(sysconfig.get_path(\'scripts\', \'nt_user\'))"))\n'
    '  \$scriptsDir = (\$scripts.Output -split "`r?`n" | Where-Object { \$_.Trim() } | Select-Object -Last 1)\n'
    '  if (\$scripts.Code -eq 0 -and \$scriptsDir) { Add-UserPath \$scriptsDir.Trim() }\n'
    '  Complete-Step \'pymobiledevice3\' (\$pipCode -eq 0) \'pymobiledevice3\'\n'
    '}\n'
    '\n'
    '# Partial runs (XCROSS_SETUP_ONLY) stop here: the summary below checks the\n'
    '# whole host, including parts this run was told to skip.\n'
    'if (\$Only.Count -gt 0) {\n'
    '  if (\$script:FailedSteps.Count -gt 0) {\n'
    '    Write-Host \'\'\n'
    '    Write-Host "Setup could not install: \$(\$script:FailedSteps -join \', \')" -ForegroundColor Yellow\n'
    '    exit 1\n'
    '  }\n'
    '  Write-Info "Installed requested components: \$(\$Only -join \', \')"\n'
    '  exit 0\n'
    '}\n'
    '\n'
    '\$problems = @()\n'
    '\$swiftVersion = Get-SwiftVersion\n'
    'if (-not \$swiftVersion) {\n'
    '  \$problems += \'swift is not on PATH (open a new terminal after installing, or see https://www.swift.org/install/windows/)\'\n'
    '} elseif (\$swiftVersion -lt \$MinSwift) {\n'
    '  \$problems += "Swift \$swiftVersion is older than \$MinSwift (\$(\$Hint.Swift))"\n'
    '}\n'
    '\$clangMajor = Get-ToolMajor \'clang\' \'clang version (\\d+)\'\n'
    'if (-not \$clangMajor -or \$clangMajor -lt \$MinClang) {\n'
    '  \$problems += "clang on PATH is \$(if (\$clangMajor) { \$clangMajor } else { \'missing\' }); Clang \$MinClang+ is required (\$(\$Hint.Llvm))"\n'
    '}\n'
    '\$lldMajor = Get-ToolMajor \'ld64.lld\' \'LLD (\\d+)\\.\'\n'
    'if (-not \$lldMajor) {\n'
    '  \$problems += "ld64.lld is not on PATH (\$(\$Hint.Llvm), then add LLVM\'s bin directory to PATH)"\n'
    '} elseif (\$lldMajor -lt \$MinLld) {\n'
    '  \$problems += "ld64.lld is LLD \$lldMajor; \$MinLld or newer is required for Objective-C plugins"\n'
    '}\n'
    'if (-not (Get-Command llvm-ar -ErrorAction SilentlyContinue)) {\n'
    '  \$problems += \'llvm-ar is not on PATH\'\n'
    '}\n'
    'if (-not \$python) {\n'
    '  \$problems += "Python 3 was not found (\$(\$Hint.Python))"\n'
    '} elseif ((Invoke-Probe \$python.Path (\$python.Args + @(\'-c\', \'import pymobiledevice3\'))).Code -ne 0) {\n'
    '  \$problems += \'pymobiledevice3 is not importable\'\n'
    '}\n'
    'if (-not (Get-Command flutter -ErrorAction SilentlyContinue)) {\n'
    '  Write-Warn \'Flutter is not on PATH; install it from https://docs.flutter.dev/get-started/install/windows for `xcross flutter`.\'\n'
    '}\n'
    '\n'
    'if (\$problems.Count -gt 0) {\n'
    '  Write-Host \'\'\n'
    '  Write-Host \'Setup finished with problems:\' -ForegroundColor Yellow\n'
    '  \$problems | ForEach-Object { Write-Host "  - \$_" }\n'
    '  exit 1\n'
    '}\n'
    'Write-Info \'xcross requirements installed. Open a new terminal so PATH changes take effect.\'\n'
    'exit 0\n';

const _direct =
    '#Requires -Version 5.1\n'
    '<#\n'
    '.SYNOPSIS\n'
    '  Installs the xcross host requirements on Windows without a package manager.\n'
    '\n'
    '.DESCRIPTION\n'
    '  Used by `xcross setup` when neither winget, Scoop nor Chocolatey is\n'
    '  installed (or with `xcross setup --manager direct`). Downloads each vendor\n'
    '  installer itself:\n'
    '\n'
    '    1. Visual Studio 2022 Build Tools (MSVC + Windows SDK, which Swift links\n'
    '       against) from https://aka.ms/vs/17/release/vs_BuildTools.exe, run only\n'
    '       with a valid Microsoft Authenticode signature.\n'
    '    2. Swift 6.4+ from download.swift.org (latest release, or\n'
    '       XCROSS_SWIFT_VERSION), run only with a valid Apple signature and, when\n'
    '       XCROSS_SWIFT_SHA256 is set, a matching SHA-256.\n'
    '    3. LLVM 20+ from the llvm/llvm-project GitHub release (latest, or\n'
    '       XCROSS_LLVM_VERSION), checked against GitHub\'s recorded asset digest\n'
    '       or XCROSS_LLVM_SHA256. XCROSS_LLVM_DIR picks the install root.\n'
    '    4. Python 3.13 from python.org (latest 3.13.x, or XCROSS_PYTHON_VERSION),\n'
    '       checked against python.org\'s published SHA-256 and the Python Software\n'
    '       Foundation signature.\n'
    '    5. pymobiledevice3 into the user site-packages.\n'
    '\n'
    '  XCROSS_SETUP_ONLY=vs,swift,llvm,python,pymobiledevice3 (set by\n'
    '  `xcross setup --only`) installs just that subset and skips the final\n'
    '  check (CI uses it for pinned toolchains).\n'
    '\n'
    '  Every installer is announced with its URL and needs a "y" before it runs.\n'
    '  -Yes (or XCROSS_SETUP_ASSUME_YES=1, which `xcross setup --yes` sets)\n'
    '  accepts those prompts up front. Installers that need elevation raise their\n'
    '  own UAC prompt.\n'
    '\n'
    '  Flutter stays manual: https://docs.flutter.dev/get-started/install/windows\n'
    '\n'
    '.PARAMETER Yes\n'
    '  Install everything without asking.\n'
    '\n'
    '.EXAMPLE\n'
    '  powershell -NoProfile -ExecutionPolicy Bypass -File direct.ps1\n'
    '#>\n'
    '[CmdletBinding()]\n'
    'param(\n'
    '  [Alias(\'y\')]\n'
    '  [switch]\$Yes\n'
    ')\n'
    '\n'
    '\$ErrorActionPreference = \'Stop\'\n'
    '# Windows PowerShell 5.1 may still default to TLS 1.0.\n'
    '[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12\n'
    '\$AssumeYes = \$Yes.IsPresent -or (\$env:XCROSS_SETUP_ASSUME_YES -eq \'1\')\n'
    '\n'
    '\$MinClang = 20\n'
    '\$MinLld = 19\n'
    '\$MinSwift = [version]\'6.4\'\n'
    '\n'
    'function Write-Info([string]\$Message) { Write-Host "==> \$Message" }\n'
    'function Write-Warn([string]\$Message) { Write-Warning \$Message }\n'
    '\n'
    '\$CanPrompt = [Environment]::UserInteractive -and -not [Console]::IsInputRedirected\n'
    '\n'
    '# Machine-readable progress for xcross. With XCROSS_SETUP_EVENTS=1 (set by\n'
    '# `xcross setup` when it reports NDJSON events) each install step prints a\n'
    '# `##xcross {"step":...,"status":...,"label":...}` line, which xcross turns\n'
    '# into a step event; terminal users never see them.\n'
    '\$EmitSteps = \$env:XCROSS_SETUP_EVENTS -eq \'1\'\n'
    '\$script:Declined = \$false\n'
    '\$script:FailedSteps = @()\n'
    'function Write-Step([string]\$Step, [string]\$Status, [string]\$Label) {\n'
    '  if (\$Status -eq \'start\') { \$script:Declined = \$false }\n'
    '  if (\$Status -eq \'failed\') { \$script:FailedSteps += \$Step }\n'
    '  if (-not \$EmitSteps) { return }\n'
    '  \$marker = [ordered]@{ step = \$Step; status = \$Status; label = \$Label }\n'
    '  Write-Host "##xcross \$(\$marker | ConvertTo-Json -Compress)"\n'
    '}\n'
    '\n'
    '# Ends a step begun with Write-Step: done when \$Ok, skipped when the user\n'
    '# declined its prompt, failed otherwise.\n'
    'function Complete-Step([string]\$Step, \$Ok, [string]\$Label) {\n'
    '  \$status = if (\$Ok) { \'done\' } elseif (\$script:Declined) { \'skipped\' } else { \'failed\' }\n'
    '  Write-Step \$Step \$status \$Label\n'
    '}\n'
    '\n'
    '# Ask before installing third-party software. Returns \$true to proceed.\n'
    'function Confirm-Install([string]\$Name, [string]\$Url, [string]\$What) {\n'
    '  Write-Host \'\'\n'
    '  Write-Host "xcross setup wants to install \$Name"\n'
    '  Write-Host "  from: \$Url"\n'
    '  Write-Host "  what: \$What"\n'
    '  if (\$AssumeYes) {\n'
    '    Write-Host \'Proceeding (-Yes).\'\n'
    '    return \$true\n'
    '  }\n'
    '  if (-not \$CanPrompt) {\n'
    '    Write-Warn "No terminal to confirm \$Name; skipping it (re-run with -Yes to accept)."\n'
    '    \$script:Declined = \$true\n'
    '    return \$false\n'
    '  }\n'
    '  \$answer = Read-Host "Install \$Name? [y/N]"\n'
    '  if (\$answer -match \'^(y|yes)\$\') { return \$true }\n'
    '  Write-Host "Skipped \$Name."\n'
    '  \$script:Declined = \$true\n'
    '  return \$false\n'
    '}\n'
    '\n'
    '# Re-read PATH and SDKROOT from the registry so newly installed tools resolve\n'
    '# in this session without a new terminal.\n'
    'function Update-SessionEnvironment {\n'
    '  \$machine = [Environment]::GetEnvironmentVariable(\'Path\', \'Machine\')\n'
    '  \$user = [Environment]::GetEnvironmentVariable(\'Path\', \'User\')\n'
    '  \$session = @(\$env:Path -split \';\' | Where-Object { \$_ })\n'
    '  \$registered = @(@(\$machine, \$user) -join \';\' -split \';\' | Where-Object { \$_ -and \$session -notcontains \$_ })\n'
    '  \$env:Path = (@(\$session) + \$registered | Select-Object -Unique) -join \';\'\n'
    '  foreach (\$scope in \'User\', \'Machine\') {\n'
    '    \$sdk = [Environment]::GetEnvironmentVariable(\'SDKROOT\', \$scope)\n'
    '    if (\$sdk) { \$env:SDKROOT = \$sdk; break }\n'
    '  }\n'
    '}\n'
    '\n'
    'function Add-UserPath([string]\$Directory) {\n'
    '  \$user = [Environment]::GetEnvironmentVariable(\'Path\', \'User\')\n'
    '  \$entries = @(\$user -split \';\' | Where-Object { \$_ })\n'
    '  if (\$entries -notcontains \$Directory) {\n'
    '    [Environment]::SetEnvironmentVariable(\'Path\', ((\$entries + \$Directory) -join \';\'), \'User\')\n'
    '    Write-Info "Added \$Directory to the user PATH"\n'
    '  }\n'
    '  if ((@(\$env:Path -split \';\') -notcontains \$Directory)) {\n'
    '    \$env:Path = "\$Directory;\$env:Path"\n'
    '  }\n'
    '}\n'
    '\n'
    '# Run a native command, returning its combined output and exit code. Windows\n'
    '# PowerShell 5.1 turns redirected native stderr into terminating errors under\n'
    '# ErrorActionPreference=Stop, so probes relax it locally.\n'
    'function Invoke-Probe([string]\$Path, [string[]]\$Arguments) {\n'
    '  \$ErrorActionPreference = \'Continue\'\n'
    '  \$output = (& \$Path @Arguments 2>&1 | Out-String)\n'
    '  return @{ Output = \$output; Code = \$LASTEXITCODE }\n'
    '}\n'
    '\n'
    '# Run a native command with its output on the console; returns the exit code.\n'
    '# Output goes to the host, not the pipeline, or callers would receive the\n'
    '# command\'s stdout as part of the return value.\n'
    'function Invoke-Native([string]\$Path, [string[]]\$Arguments) {\n'
    '  Write-Info "\$Path \$(\$Arguments -join \' \')"\n'
    '  \$ErrorActionPreference = \'Continue\'\n'
    '  & \$Path @Arguments | Out-Host\n'
    '  return \$LASTEXITCODE\n'
    '}\n'
    '\n'
    'function Get-ToolMajor([string]\$Command, [string]\$Pattern) {\n'
    '  \$tool = Get-Command \$Command -ErrorAction SilentlyContinue\n'
    '  if (-not \$tool) { return \$null }\n'
    '  \$text = (Invoke-Probe \$tool.Source @(\'--version\')).Output\n'
    '  if (\$text -match \$Pattern) { return [int]\$Matches[1] }\n'
    '  return \$null\n'
    '}\n'
    '\n'
    'function Get-SwiftVersion {\n'
    '  \$swift = Get-Command swift -ErrorAction SilentlyContinue\n'
    '  if (-not \$swift) { return \$null }\n'
    '  \$text = (Invoke-Probe \$swift.Source @(\'--version\')).Output\n'
    '  if (\$text -match \'Swift version (\\d+\\.\\d+)\') { return [version]\$Matches[1] }\n'
    '  return \$null\n'
    '}\n'
    '\n'
    '# The LLVM installer does not touch PATH; xcross finds these directories on\n'
    '# its own, but PATH makes clang usable everywhere.\n'
    'function Find-LlvmBin {\n'
    '  foreach (\$root in @(\$env:ProgramW6432, \$env:ProgramFiles, \${env:ProgramFiles(x86)})) {\n'
    '    if (-not \$root) { continue }\n'
    '    \$bin = Join-Path \$root \'LLVM\\bin\'\n'
    '    if (Test-Path (Join-Path \$bin \'clang.exe\')) { return \$bin }\n'
    '  }\n'
    '  return \$null\n'
    '}\n'
    '\n'
    '# studio: 009 - the Swift toolchain ships an ld64.lld without Mach-O iOS\n'
    '# support, so finding *an* ld64.lld is not enough. Like xcross\'s own probe\n'
    '# (darwin_toolchain_resolver.dart), link a 56-byte empty arm64 iOS object\n'
    '# into a dylib: an unsupported linker rejects the platform once it reads it.\n'
    'function Test-IosLinker {\n'
    '  \$words = @(0xfeedfacfL, 0x0100000c, 0, 1, 1, 24, 0, 0, 0x32, 24, 2, 0x000d0000, 0x000d0000, 0)\n'
    '  \$bytes = [byte[]]@(\$words | ForEach-Object { [BitConverter]::GetBytes([uint32]\$_) } | ForEach-Object { \$_ })\n'
    '  \$dir = Join-Path ([IO.Path]::GetTempPath()) ("xcross-ld64-probe-" + [guid]::NewGuid())\n'
    '  New-Item -ItemType Directory -Path \$dir -Force | Out-Null\n'
    '  \$object = Join-Path \$dir \'probe.o\'\n'
    '  [IO.File]::WriteAllBytes(\$object, \$bytes)\n'
    '  \$candidates = @()\n'
    '  \$llvm = Find-LlvmBin\n'
    '  if (\$llvm) { \$candidates += (Join-Path \$llvm \'ld64.lld.exe\') }\n'
    '  \$candidates += @(Get-Command ld64.lld -All -ErrorAction SilentlyContinue | ForEach-Object { \$_.Source })\n'
    '  try {\n'
    '    foreach (\$lld in \$candidates) {\n'
    '      if (-not (Test-Path \$lld)) { continue }\n'
    '      \$probe = Invoke-Probe \$lld @(\'-arch\', \'arm64\', \'-platform_version\', \'ios\', \'13.0\', \'13.0\', \'-dylib\', \'-o\', "\$object.dylib", \$object)\n'
    '      if (\$probe.Output -notmatch \'does not support linking for platform|unknown platform|missing or unsupported -arch\') { return \$true }\n'
    '    }\n'
    '    return \$false\n'
    '  } finally {\n'
    '    Remove-Item -Recurse -Force \$dir -ErrorAction SilentlyContinue\n'
    '  }\n'
    '}\n'
    '\n'
    '# The Microsoft Store "python.exe" alias is a stub that only opens the Store.\n'
    'function Find-Python {\n'
    '  foreach (\$candidate in @(\n'
    '      @{ Command = \'py\'; Args = @(\'-3\') },\n'
    '      @{ Command = \'python\'; Args = @() },\n'
    '      @{ Command = \'python3\'; Args = @() })) {\n'
    '    \$cmd = Get-Command \$candidate.Command -ErrorAction SilentlyContinue\n'
    '    if (-not \$cmd -or \$cmd.Source -like \'*\\WindowsApps\\*\') { continue }\n'
    '    \$probeArgs = \$candidate.Args + @(\'-c\', \'import sys; assert sys.version_info >= (3, 9)\')\n'
    '    if ((Invoke-Probe \$cmd.Source \$probeArgs).Code -eq 0) { return @{ Path = \$cmd.Source; Args = \$candidate.Args } }\n'
    '  }\n'
    '  return \$null\n'
    '}\n'
    '\n'
    '# Native architecture, even from an emulated x64 PowerShell on ARM64.\n'
    '\$arch = \$env:PROCESSOR_ARCHITEW6432\n'
    'if (-not \$arch) { \$arch = \$env:PROCESSOR_ARCHITECTURE }\n'
    '\$isArm64 = \$arch -eq \'ARM64\'\n'
    '\n'
    '# MSVC + Windows SDK components Swift for Windows links against.\n'
    '\$vcComponent = if (\$isArm64) {\n'
    '  \'Microsoft.VisualStudio.Component.VC.Tools.ARM64\'\n'
    '} else {\n'
    '  \'Microsoft.VisualStudio.Component.VC.Tools.x86.x64\'\n'
    '}\n'
    '\$vsComponents = @(\n'
    '  \'Microsoft.VisualStudio.Component.Windows11SDK.22621\',\n'
    '  \'Microsoft.VisualStudio.Component.VC.Tools.x86.x64\'\n'
    ')\n'
    'if (\$isArm64) { \$vsComponents += \'Microsoft.VisualStudio.Component.VC.Tools.ARM64\' }\n'
    '\$vsAdd = @(\$vsComponents | ForEach-Object { \'--add\'; \$_ })\n'
    '\n'
    'function Test-Msvc {\n'
    '  \$programFilesX86 = if (\${env:ProgramFiles(x86)}) { \${env:ProgramFiles(x86)} } else { \$env:ProgramFiles }\n'
    '  if (-not \$programFilesX86) { return \$false }\n'
    '  \$vswhere = Join-Path \$programFilesX86 \'Microsoft Visual Studio\\Installer\\vswhere.exe\'\n'
    '  if (-not (Test-Path \$vswhere)) { return \$false }\n'
    '  \$found = Invoke-Probe \$vswhere @(\'-latest\', \'-products\', \'*\', \'-requires\', \$vcComponent, \'-property\', \'installationPath\')\n'
    '  return \$found.Code -eq 0 -and [bool]\$found.Output.Trim()\n'
    '}\n'
    '\n'
    'function Test-Elevated {\n'
    '  try {\n'
    '    \$identity = [Security.Principal.WindowsIdentity]::GetCurrent()\n'
    '  } catch {\n'
    '    return \$false # Not Windows.\n'
    '  }\n'
    '  return ([Security.Principal.WindowsPrincipal]\$identity).IsInRole(\n'
    '    [Security.Principal.WindowsBuiltInRole]::Administrator)\n'
    '}\n'
    '\n'
    '# Download a vendor installer, check it against \$Sha256 and/or a valid\n'
    '# Authenticode signature from \$Signer (at least one is required), then run it.\n'
    'function Install-SignedInstaller {\n'
    '  param(\n'
    '    [string]\$Name, [string]\$Url, [string]\$What,\n'
    '    [string[]]\$Arguments, [string]\$Signer, [string]\$Sha256,\n'
    '    [int[]]\$OkCodes = @(0, 3010)\n'
    '  )\n'
    '  if (-not \$Signer -and -not \$Sha256) { throw "No way to verify the \$Name installer." }\n'
    '  if (\$Signer -and -not (Get-Command Get-AuthenticodeSignature -ErrorAction SilentlyContinue)) {\n'
    '    Write-Warn "Cannot verify the \$Name installer signature here; install it manually from \$Url."\n'
    '    return \$false\n'
    '  }\n'
    '  if (-not (Confirm-Install "\$Name (official installer)" \$Url \$What)) { return \$false }\n'
    '  \$file = Join-Path ([IO.Path]::GetTempPath()) ("xcross-" + [IO.Path]::GetFileName(([uri]\$Url).AbsolutePath))\n'
    '  try {\n'
    '    Write-Info "Downloading \$Url"\n'
    '    \$ProgressPreference = \'SilentlyContinue\'\n'
    '    Invoke-WebRequest -Uri \$Url -OutFile \$file -UseBasicParsing\n'
    '    if (\$Sha256) {\n'
    '      \$hash = (Get-FileHash -LiteralPath \$file -Algorithm SHA256).Hash\n'
    '      if (\$hash -ne \$Sha256.Trim().ToUpperInvariant()) {\n'
    '        Write-Warn "Refusing to run \${Name}: SHA-256 \$hash, expected \$Sha256."\n'
    '        return \$false\n'
    '      }\n'
    '      Write-Info "SHA-256 \$hash"\n'
    '    }\n'
    '    if (\$Signer) {\n'
    '      \$signature = Get-AuthenticodeSignature -FilePath \$file\n'
    '      \$subject = if (\$signature.SignerCertificate) { \$signature.SignerCertificate.Subject } else { \'<unsigned>\' }\n'
    '      if (\$signature.Status -ne \'Valid\' -or \$subject -notlike "*\$Signer*") {\n'
    '        Write-Warn "Refusing to run \${Name}: signature \$(\$signature.Status), signer \$subject."\n'
    '        return \$false\n'
    '      }\n'
    '      Write-Info "Signed by \$subject"\n'
    '    }\n'
    '    \$process = if (\$file -like \'*.msi\') {\n'
    '      Start-Process -FilePath \'msiexec.exe\' -ArgumentList (@(\'/i\', "`"\$file`"") + \$Arguments) -Wait -PassThru\n'
    '    } else {\n'
    '      Start-Process -FilePath \$file -ArgumentList \$Arguments -Wait -PassThru\n'
    '    }\n'
    '    Update-SessionEnvironment\n'
    '    if (\$process.ExitCode -eq 3010) { Write-Warn "\$Name asks for a reboot to finish installing." }\n'
    '    if (\$OkCodes -notcontains \$process.ExitCode) {\n'
    '      Write-Warn "\$Name installer failed with exit code \$(\$process.ExitCode)."\n'
    '      return \$false\n'
    '    }\n'
    '    return \$true\n'
    '  } finally {\n'
    '    Remove-Item -LiteralPath \$file -Force -ErrorAction SilentlyContinue\n'
    '  }\n'
    '}\n'
    '\n'
    '# Invoke-RestMethod writes a top-level JSON array to the pipeline as a single\n'
    '# object in Windows PowerShell 5.1; enumerate it so filters see each element.\n'
    'function Get-JsonArray([string]\$Url) {\n'
    '  Invoke-RestMethod -UseBasicParsing -Headers @{ \'User-Agent\' = \'xcross-setup\' } \$Url | ForEach-Object { \$_ }\n'
    '}\n'
    '\n'
    '# ---------------------------------------------------------------------------\n'
    '# Direct vendor downloads\n'
    '# ---------------------------------------------------------------------------\n'
    '\n'
    '# Latest releases unless pinned. A pin with a SHA-256 is checked against it;\n'
    '# otherwise the GitHub/python.org published digest is used, and the\n'
    '# Authenticode signer is checked for vendors that sign their installers.\n'
    '\$SwiftPin = \$env:XCROSS_SWIFT_VERSION         # e.g. 6.4.0\n'
    '\$SwiftPinSha = \$env:XCROSS_SWIFT_SHA256\n'
    '\$LlvmPin = \$env:XCROSS_LLVM_VERSION           # e.g. 22.1.8\n'
    '\$LlvmPinSha = \$env:XCROSS_LLVM_SHA256\n'
    '\$LlvmDir = \$env:XCROSS_LLVM_DIR               # install root, default Program Files\\LLVM\n'
    '\$PythonPin = \$env:XCROSS_PYTHON_VERSION       # e.g. 3.13.16\n'
    '# Comma-separated subset of vs,swift,llvm,python,pymobiledevice3 to install\n'
    '# (default: all).\n'
    '\$Only = @((\$env:XCROSS_SETUP_ONLY -split \',\') | ForEach-Object { \$_.Trim().ToLowerInvariant() } | Where-Object { \$_ })\n'
    'function Test-Wanted([string]\$Component) { \$Only.Count -eq 0 -or \$Only -contains \$Component }\n'
    '\n'
    '# Anonymous GitHub API calls share a 60/hour limit per IP, which CI runners\n'
    '# exhaust quickly; send a token when one is available.\n'
    'function Get-GitHubRelease([string]\$Tag) {\n'
    '  \$api = \'https://api.github.com/repos/llvm/llvm-project/releases/\' + \$(if (\$Tag) { "tags/\$Tag" } else { \'latest\' })\n'
    '  \$headers = @{ \'User-Agent\' = \'xcross-setup\'; \'Accept\' = \'application/vnd.github+json\' }\n'
    '  \$token = if (\$env:GITHUB_TOKEN) { \$env:GITHUB_TOKEN } elseif (\$env:GH_TOKEN) { \$env:GH_TOKEN }\n'
    '  if (\$token) { \$headers[\'Authorization\'] = "Bearer \$token" }\n'
    '  return Invoke-RestMethod -UseBasicParsing -Headers \$headers \$api\n'
    '}\n'
    '\n'
    '# A pinned version with a pinned SHA-256 needs no API lookup: the asset URL is\n'
    '# predictable and the digest comes from the pin.\n'
    'function Get-PinnedLlvmRelease([string]\$Version, [string]\$Suffix) {\n'
    '  \$major = [int](\$Version -split \'\\.\')[0]\n'
    '  # LLVM 22 ships NSIS .exe installers, LLVM 23+ ships .msi.\n'
    '  \$ext = if (\$major -ge 23) { \'msi\' } else { \'exe\' }\n'
    '  \$name = "LLVM-\$Version-\$Suffix.\$ext"\n'
    '  return [pscustomobject]@{\n'
    '    tag_name = "llvmorg-\$Version"\n'
    '    assets = @([pscustomobject]@{\n'
    '        name = \$name\n'
    '        browser_download_url = "https://github.com/llvm/llvm-project/releases/download/llvmorg-\$Version/\$name"\n'
    '        digest = \$null\n'
    '      })\n'
    '  }\n'
    '}\n'
    '\n'
