    '  if (\$python) {\n'
    '    Write-Step \'python\' \'skipped\' \'Python 3 (already installed)\'\n'
    '  } else {\n'
    '    Write-Step \'python\' \'start\' \'Python 3.13\'\n'
    '    \$ok = \$false\n'
    '    # Invoke-RestMethod emits a JSON array as one object; Get-JsonArray unrolls it.\n'
    '    \$releases = @(Get-JsonArray \'https://www.python.org/api/v2/downloads/release/?is_published=true&pre_release=false\')\n'
    '    \$wanted = if (\$PythonPin) { "Python \$PythonPin" } else { \$null }\n'
    '    \$release = \$releases |\n'
    '      Where-Object { if (\$wanted) { \$_.name -eq \$wanted } else { \$_.name -like \'Python 3.13.*\' } } |\n'
    '      Sort-Object release_date | Select-Object -Last 1\n'
    '    \$id = (\$release.resource_uri -split \'/\' | Where-Object { \$_ })[-1]\n'
    '    \$label = if (\$isArm64) { \'Windows installer (ARM64)\' } else { \'Windows installer (64-bit)\' }\n'
    '    \$file = @(Get-JsonArray "https://www.python.org/api/v2/downloads/release_file/?release=\$id") |\n'
