    '    }\n'
    '    Complete-Step \'python\' \$ok \'Python 3.13\'\n'
    '  }\n'
    '}\n'
    '\n'
    '\$Hint = @{\n'
    '  Swift  = \'https://www.swift.org/install/windows/\'\n'
    '  Llvm   = \'https://github.com/llvm/llvm-project/releases\'\n'
    '  Python = \'https://www.python.org/downloads/windows/\'\n'
    '}\n'
