    '\n'
    '# An LLVM installed outside Scoop (the official installer) does not touch\n'
    '# PATH; Test-IosLinker probes its ld64.lld too.\n'
    'function Find-LlvmBin {\n'
    '  foreach (\$root in @(\$env:ProgramW6432, \$env:ProgramFiles, \${env:ProgramFiles(x86)})) {\n'
